        (assign, ":ransom_chance", 45),
        (assign, ":exchange_chance", 25),
        (assign, ":remain_chance", 30),
        (store_random_in_range, "$player_ransom_amount", 4, 7),
        (val_mul, "$player_ransom_amount", 100),
        (store_mul, ":level_fee", ":player_level", 35),
        (val_add, "$player_ransom_amount", ":level_fee"),
        (store_mul, ":renown_fee", ":renown_factor", 60),
        (val_add, "$player_ransom_amount", ":renown_fee"),
